    val ps = toListFromImmutable(NodeUtil.getParams(f))
    val qs = toListFromImmutable(NodeUtil.getParams(fd))
    ps.length == qs.length &&
    ps.zip(qs).forall { case (p, q) =>
      paramWithoutType(p) ||
      (same(toOption(p.getIdType), toOption(q.getIdType)) &&
